    "content": "const BASE_URL = import.meta.env.VITE_API_URL ?? "https://smartloansbackend.azurewebsites.net";

export interface PosRewardCatalogItem {
  catalogItemId: number;
  companyId: number;
  name: string;
  rewardType: 'discount' | 'freeProduct';
  requiredPoints: number;
  discountValue?: number | null; // Allow null as it's nullable in DB and set to null when not applicable
  freeProductId?: number | null; // Allow null as it's nullable in DB and set to null when not applicable
  isActive: boolean;
  description?: string | null; // Allow null as it's nullable in DB
  created_At: string;
  updated_at?: string | null;
}

export interface PosRewardCatalogItemListResponse {
  posRewardCatalogItems: PosRewardCatalogItem[];
}

export type CreatePosRewardCatalogItemRequest = Omit<PosRewardCatalogItem, "catalogItemId" | "created_At" | "updated_at">;

// GET ALL — POST /all_posRewardCatalogItems
export async function getAllPosRewardCatalogItems(companyId: number): Promise<PosRewardCatalogItem[]> {
  const res = await fetch(BASE_URL + "/all_posRewardCatalogItems", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "posRewardCatalogItems": [{ "companyId": companyId }] }),
  });
  if (!res.ok) throw new Error(await res.text());
  const data: PosRewardCatalogItemListResponse = await res.json();
  return data.posRewardCatalogItems ?? [];   // unwrap: SP wraps array under plural key
}

// CREATE — action: 1
export async function createPosRewardCatalogItem(payload: CreatePosRewardCatalogItemRequest): Promise<PosRewardCatalogItem> {
  const res = await fetch(BASE_URL + "/posRewardCatalogItems", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "posRewardCatalogItems": [{ "action": 1, ...payload }] }),
  });
  if (!res.ok) throw new Error(await res.text());
  return await res.json();
}

// UPDATE — action: 2
export async function updatePosRewardCatalogItem(id: number, payload: Partial<PosRewardCatalogItem>): Promise<PosRewardCatalogItem> {
  const res = await fetch(BASE_URL + "/posRewardCatalogItems", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "posRewardCatalogItems": [{ "action": 2, "catalogItemId": id, ...payload }] }),
  });
  if (!res.ok) throw new Error(await res.text());
  return await res.json();
}

// DELETE — action: 3
export async function deletePosRewardCatalogItem(id: number, companyId: number): Promise<void> {
  const res = await fetch(BASE_URL + "/posRewardCatalogItems", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ "posRewardCatalogItems": [{ "action": 3, "catalogItemId": id, "companyId": companyId }] }),
  });
  if (!res.ok) throw new Error(await res.text());
}

