  IonSpinner,
  IonBadge,
  IonCard,
  IonCardContent,
  IonSearchbar,
  useIonViewWillEnter,
  IonHeader,
  IonButtons,
} from '@ionic/react';
import { add, create, trash, close, saveOutline } from 'ionicons/icons';
import Header from '../components/Header';
import AlertPopover from '../components/PopOver/AlertPopover';
import MailPopover from '../components/PopOver/MailPopover';
import { useUser } from '../contexts/UserContext';
import {
  PosRewardCatalogItem,
  CreatePosRewardCatalogItemRequest,
  getAllPosRewardCatalogItems,
  createPosRewardCatalogItem,
  updatePosRewardCatalogItem,
  deletePosRewardCatalogItem,
  Product, // For freeProductId selection
  getAllProducts, // For freeProductId selection
} from '../api/posRewardCatalogItemApi';
import { InputInputEventDetail, SelectChangeEventDetail, ToggleChangeEventDetail, SearchbarInputEventDetail } from '@ionic/core';

const toHermosillo = (utc: string | undefined | null): string => {
  if (!utc) return '';
  const d = new Date(utc.includes('Z') ? utc : utc + 'Z');
  return new Date(d.getTime() - 7 * 60 * 60 * 1000).toLocaleString();
};

interface FormState {
  name: string;
  rewardType: 'discount' | 'freeProduct';
  requiredPoints: number | '';
  discountValue: number | '';
  freeProductId: number | '';
  isActive: boolean;
  description: string;
}

const PosRewardCatalogItemPage: React.FC = () => {
  const { companyId } = useUser();
  const [items, setItems] = useState<PosRewardCatalogItem[]>([]);
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');
  const [showToast, setShowToast] = useState(false);
  const [toastMessage, setToastMessage] = useState('');

  const [showModal, setShowModal] = useState(false);
  const [isNewItem, setIsNewItem] = useState(true);
  const [editingItem, setEditingItem] = useState<PosRewardCatalogItem | null>(null);
  const [formState, setFormState] = useState<FormState>({
    name: '',
    rewardType: 'discount',
    requiredPoints: '',
    discountValue: '',
    freeProductId: '',
    isActive: true,
    description: '',
  });
  const [formErrors, setFormErrors] = useState<Partial<Record<keyof FormState, string>>>({});

  const [showDeleteAlert, setShowDeleteAlert] = useState(false);
  const [itemToDelete, setItemToDelete] = useState<PosRewardCatalogItem | null>(null);

  const [searchText, setSearchText] = useState('');

  const [products, setProducts] = useState<Product[]>([]); // For freeProductId dropdown

  // Infinite scroll state
  const [currentPage, setCurrentPage] = useState(0);
  const itemsPerPage = 20; // Default items per page
  const [infiniteScrollDisabled, setInfiniteScrollDisabled] = useState(false);
  const infiniteScrollRef = useRef<HTMLIonInfiniteScrollElement>(null);

  const [popoverState, setPopoverState] = useState<{
    showAlertPopover: boolean;
    showMailPopover: boolean;
    event?: Event;
  }>({ showAlertPopover: false, showMailPopover: false });

  const presentAlertPopover = (e: React.MouseEvent) =>
    setPopoverState({ ...popoverState, showAlertPopover: true, event: e.nativeEvent });
  const dismissAlertPopover = () =>
    setPopoverState({ ...popoverState, showAlertPopover: false });
  const presentMailPopover = (e: React.MouseEvent) =>
    setPopoverState({ ...popoverState, showMailPopover: true, event: e.nativeEvent });
  const dismissMailPopover = () =>
    setPopoverState({ ...popoverState, showMailPopover: false });

  const resetForm = () => {
    setFormState({
      name: '',
      rewardType: 'discount',
      requiredPoints: '',
      discountValue: '',
      freeProductId: '',
      isActive: true,
      description: '',
    });
    setFormErrors({});
    setEditingItem(null);
  };

  const validateForm = (): boolean => {
    const errors: Partial<Record<keyof FormState, string>> = {};
    if (!formState.name || formState.name.trim() === '') {
      errors.name = 'El nombre es requerido.';
    }
    if (formState.requiredPoints === '' || isNaN(Number(formState.requiredPoints)) || Number(formState.requiredPoints) <= 0) {
      errors.requiredPoints = 'Los puntos requeridos deben ser un número positivo.';
    }
    if (formState.rewardType === 'discount' && (formState.discountValue === '' || isNaN(Number(formState.discountValue)) || Number(formState.discountValue) <= 0)) {
      errors.discountValue = 'El valor del descuento debe ser un número positivo.';
    }
    if (formState.rewardType === 'freeProduct' && (formState.freeProductId === '' || isNaN(Number(formState.freeProductId)))) {
      errors.freeProductId = 'Debe seleccionar un producto.';
    }

    setFormErrors(errors);
    return Object.keys(errors).length === 0;
  };

  const fetchProducts = async () => {
    if (!companyId) return;
    try {
      const fetchedProducts = await getAllProducts(companyId);
      setProducts(fetchedProducts);
    } catch (err) {
      setError((err as Error).message ?? 'Error al cargar productos.');
      setToastMessage('Error al cargar productos.');
      setShowToast(true);
    }
  };

  const fetchItems = async (page: number = 0) => {
    if (!companyId) return;
    setLoading(true);
    setError('');
    try {
      const allItems = await getAllPosRewardCatalogItems(companyId);
      const filteredItems = allItems.filter(item =>
        item.name.toLowerCase().includes(searchText.toLowerCase())
      );

      const startIndex = page * itemsPerPage;
      const newItems = filteredItems.slice(startIndex, startIndex + itemsPerPage);

      if (page === 0) {
        setItems(newItems);
      } else {
        setItems(prevItems => [...prevItems, ...newItems]);
      }
      setCurrentPage(page);
      setInfiniteScrollDisabled(filteredItems.length <= startIndex + newItems.length);

    } catch (err) {
      setError((err as Error).message ?? 'Error desconocido al cargar las recompensas.');
      setToastMessage('Error al cargar las recompensas.');
      setShowToast(true);
    } finally {
      setLoading(false);
      if (infiniteScrollRef.current) {
        infiniteScrollRef.current.complete();
      }
    }
  };

  useIonViewWillEnter(() => {
    if (companyId) {
      fetchItems(0);
      fetchProducts();
    }
  });

  useEffect(() => {
    if (companyId) {
      fetchItems(0);
      fetchProducts();
    }
  }, [companyId]);

  useEffect(() => {
    // Reset current page and fetch items when search text changes
    setCurrentPage(0);
    fetchItems(0);
  }, [searchText]);

  const loadMoreItems = async (ev: CustomEvent<void>) => {
    if (!infiniteScrollDisabled && !loading) {
      await fetchItems(currentPage + 1);
    }
    (ev.target as HTMLIonInfiniteScrollElement).complete();
  };

  const handleSave = async () => {
    if (!validateForm()) {
      return;
    }

    setSaving(true);
    setError('');
    try {
      const payload: CreatePosRewardCatalogItemRequest | Partial<PosRewardCatalogItem> = {
        companyId,
        name: formState.name,
        rewardType: formState.rewardType,
        requiredPoints: Number(formState.requiredPoints),
        isActive: formState.isActive,
        description: formState.description || null, // Ensure null for empty optional fields
      };

      if (formState.rewardType === 'discount') {
        (payload as any).discountValue = Number(formState.discountValue);
        (payload as any).freeProductId = null; 
      } else {
        (payload as any).freeProductId = Number(formState.freeProductId);
        (payload as any).discountValue = null;
      }

      if (isNewItem) {
        await createPosRewardCatalogItem(payload as CreatePosRewardCatalogItemRequest);
        setToastMessage('Recompensa creada exitosamente.');
      } else if (editingItem) {
        await updatePosRewardCatalogItem(editingItem.catalogItemId, payload);
        setToastMessage('Recompensa actualizada exitosamente.');
      }
      setShowModal(false);
      fetchItems(0); // Refresh list
      setShowToast(true);
    } catch (err) {
      setError((err as Error).message ?? 'Error al guardar la recompensa.');
      setToastMessage('Error al guardar la recompensa.');
      setShowToast(true);
    } finally {
      setSaving(false);
    }
  };

  const handleDelete = async () => {
    if (itemToDelete) {
      setLoading(true);
      setError('');
      try {
        await deletePosRewardCatalogItem(itemToDelete.catalogItemId, companyId);
        setToastMessage('Recompensa eliminada exitosamente.');
        fetchItems(0); // Refresh list
        setShowToast(true);
      } catch (err) {
        setError((err as Error).message ?? 'Error al eliminar la recompensa.');
        setToastMessage('Error al eliminar la recompensa.');
        setShowToast(true);
      } finally {
        setLoading(false);
        setItemToDelete(null);
      }
    }
  };

  const openCreateModal = () => {
    setIsNewItem(true);
    resetForm();
    setShowModal(true);
  };

  const openEditModal = (item: PosRewardCatalogItem) => {
    setIsNewItem(false);
    setEditingItem(item);
    setFormState({
      name: item.name,
      rewardType: item.rewardType,
      requiredPoints: item.requiredPoints,
      discountValue: item.discountValue ?? '',
      freeProductId: item.freeProductId ?? '',
      isActive: item.isActive,
      description: item.description ?? '',
    });
    setFormErrors({});
    setShowModal(true);
  };

  return (
    <IonPage className="pos-reward-catalog-item-page">
      <Header
        presentAlertPopover={presentAlertPopover}
        presentMailPopover={presentMailPopover}
        screenTitle="Catálogo de Recompensas POS"
      />
      <AlertPopover
        isOpen={popoverState.showAlertPopover}
        event={popoverState.event}
        onDidDismiss={dismissAlertPopover}
      />
      <MailPopover
        isOpen={popoverState.showMailPopover}
        event={popoverState.event}
        onDidDismiss={dismissMailPopover}
      />

      <IonContent fullscreen className="ion-padding">
        <IonSearchbar
          className="pos-reward-catalog-item-searchbar"
          placeholder="Buscar recompensas..."
          value={searchText}
          onIonInput={(e: CustomEvent<SearchbarInputEventDetail>) => setSearchText(e.detail.value!)}
        />

        {loading && items.length === 0 ? (
          <div className="ion-text-center ion-padding-top">
            <IonSpinner name="crescent" />
          </div>
        ) : (
          <IonList className="pos-reward-catalog-item-list">
            {items.length === 0 && !loading ? (
              <IonItem lines="none">
                <IonLabel className="ion-text-center">No hay recompensas disponibles.</IonLabel>
              </IonItem>
            ) : (
              items.map((item) => (
                <IonCard key={item.catalogItemId} className="pos-reward-catalog-item-card">
                  <IonCardContent className="pos-reward-catalog-item-card-content">
                    <div className="pos-reward-catalog-item-info">
                      <IonLabel>
                        <h2>{item.name}</h2>
                        <p>Puntos requeridos: <strong>{item.requiredPoints.toFixed(2)}</strong></p>
                        {item.rewardType === 'discount' && item.discountValue !== undefined && item.discountValue !== null && (
                          <p>Valor de descuento: <strong>${item.discountValue.toFixed(2)}</strong></p>
                        )}
                        {item.rewardType === 'freeProduct' && item.freeProductId && (
                          <p>Producto gratis: <strong>{products.find(p => p.productId === item.freeProductId)?.name || 'N/A'}</strong></p>
                        )}
                        <p>
                          Tipo: <IonBadge className={`reward-type-${item.rewardType}`}>
                            {item.rewardType === 'discount' ? 'Descuento' : 'Producto Gratis'}
                          </IonBadge>
                        </p>
                        <p>
                          Estado: <IonBadge color={item.isActive ? 'success' : 'medium'}>
                            {item.isActive ? 'Activo' : 'Inactivo'}
                          </IonBadge>
                        </p>
                        {item.description && item.description.trim() !== '' && <p>Descripción: {item.description}</p>}
                        <p className="pos-reward-catalog-item-dates">
                          Creado: {toHermosillo(item.created_At)}
                          {item.updated_at && item.updated_at.trim() !== '' && ` | Actualizado: ${toHermosillo(item.updated_at)}`}
                        </p>
                      </IonLabel>
                    </div>
                    <div className="pos-reward-catalog-item-actions">
                      <IonButton fill="clear" color="primary" onClick={() => openEditModal(item)}>
                        <IonIcon icon={create} slot="icon-only" />
                      </IonButton>
