                  className={formErrors.name ? 'ion-invalid ion-touched' : ''}
                  errorText={formErrors.name}
                />
              </div>

              <div className="pos-reward-catalog-item-form-field-group">
                <IonInput
                  fill="outline"
                  label="Puntos Requeridos *"
                  labelPlacement="floating"
                  type="number"
                  value={formState.requiredPoints}
                  onIonInput={(e: CustomEvent<InputInputEventDetail>) => setFormState(p => ({ ...p, requiredPoints: parseFloat(e.detail.value!) }))}
                  className={formErrors.requiredPoints ? 'ion-invalid ion-touched' : ''}
                  errorText={formErrors.requiredPoints}
                />
              </div>

              <div className="pos-reward-catalog-item-form-field-group">
                <IonSelect
                  fill="outline"
                  label="Tipo de Recompensa *"
                  labelPlacement="floating"
                  value={formState.rewardType}
                  onIonChange={(e: CustomEvent<SelectChangeEventDetail>) => setFormState(p => ({ ...p, rewardType: e.detail.value }))}
                >
                  <IonSelectOption value="discount">Descuento</IonSelectOption>
                  <IonSelectOption value="freeProduct">Producto Gratis</IonSelectOption>
                </IonSelect>
              </div>

              {formState.rewardType === 'discount' && (
                <div className="pos-reward-catalog-item-form-field-group">
                  <IonInput
                    fill="outline"
                    label="Valor del Descuento *"
                    labelPlacement="floating"
                    type="number"
                    value={formState.discountValue}
                    onIonInput={(e: CustomEvent<InputInputEventDetail>) => setFormState(p => ({ ...p, discountValue: parseFloat(e.detail.value!) }))}
                    className={formErrors.discountValue ? 'ion-invalid ion-touched' : ''}
                    errorText={formErrors.discountValue}
                  />
                </div>
              )}

              {formState.rewardType === 'freeProduct' && (
                <div className="pos-reward-catalog-item-form-field-group">
                  <IonSelect
                    fill="outline"
                    label="Producto Gratis *"
                    labelPlacement="floating"
                    value={formState.freeProductId}
                    onIonChange={(e: CustomEvent<SelectChangeEventDetail>) => setFormState(p => ({ ...p, freeProductId: e.detail.value }))}
                    className={formErrors.freeProductId ? 'ion-invalid ion-touched' : ''}
                    errorText={formErrors.freeProductId}
                  >
                    <IonSelectOption value="">Seleccione un producto</IonSelectOption>
                    {products.map(product => (
                      <IonSelectOption key={product.productId} value={product.productId}>
                        {product.name}
                      </IonSelectOption>
                    ))}
                  </IonSelect>
                </div>
              )}

              <div className="pos-reward-catalog-item-form-field-group ion-margin-top">
                <IonToggle
                  checked={formState.isActive}
                  onIonChange={(e: CustomEvent<ToggleChangeEventDetail>) => setFormState(p => ({ ...p, isActive: e.detail.checked }))}
                  labelPlacement="end"
                >
                  <IonLabel>Activo</IonLabel>
                </IonToggle>
              </div>

              <div className="pos-reward-catalog-item-form-field-group">
                <IonInput
                  fill="outline"
                  label="Descripción (opcional)"
                  labelPlacement="floating"
                  value={formState.description}
                  onIonInput={(e: CustomEvent<InputInputEventDetail>) => setFormState(p => ({ ...p, description: e.detail.value! }))}
                />
              </div>

              <IonButton expand="block" onClick={handleSave} disabled={saving} className="ion-margin-top">
                {saving ? <IonSpinner name="dots" /> : <><IonIcon icon={saveOutline} slot="start" /> Guardar</>}
              </IonButton>
            </form>
          </IonContent>
        </IonModal>

        <IonLoading isOpen={loading && items.length === 0} message={'Cargando recompensas...'} />
        <IonToast
          isOpen={showToast}
          message={toastMessage}
          duration={3000}
          onDidDismiss={() => setShowToast(false)}
          color={error ? 'danger' : 'success'}
        />

        <IonAlert
          isOpen={showDeleteAlert}
          onDidDismiss={() => setShowDeleteAlert(false)}
          header={'Confirmar Eliminación'}
          message={`¿Estás seguro de que quieres eliminar la recompensa "${itemToDelete?.name}"?`}
          buttons={[
            { text: 'Cancelar', role: 'cancel' },
            { text: 'Eliminar', handler: handleDelete, cssClass: 'danger' },
          ]}
        />
      </IonContent>
    </IonPage>
  );
};

export default PosRewardCatalogItemPage;
